<?php
$titulo='Inventario'; require_once 'header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{validarCsrf();$pid=(int)$_POST['producto_id'];$nuevo=max(0,(float)$_POST['nuevo_stock']);$mot=trim($_POST['motivo']??'')?:'Ajuste manual';$conn->begin_transaction();$st=$conn->prepare("SELECT nombre,stock FROM productos WHERE id=? FOR UPDATE");$st->bind_param('i',$pid);$st->execute();$p=$st->get_result()->fetch_assoc();if(!$p)throw new RuntimeException('Producto no existe.');$an=(float)$p['stock'];$dif=$nuevo-$an;$st=$conn->prepare("UPDATE productos SET stock=? WHERE id=?");$st->bind_param('di',$nuevo,$pid);$st->execute();$tipo=$dif>0?'entrada':($dif<0?'salida':'ajuste');$origen=$tipo==='entrada'?'compra':($tipo==='salida'?'salida_manual':'ajuste');$cant=abs($dif);$uid=$_SESSION['usuario']['id']??null;$obs='Cambio manual de stock';$st=$conn->prepare("INSERT INTO movimientos_inventario(producto_id,usuario_id,tipo,origen,cantidad,stock_anterior,stock_nuevo,motivo,observacion) VALUES(?,?,?,?,?,?,?,?,?)");$st->bind_param('iissdddss',$pid,$uid,$tipo,$origen,$cant,$an,$nuevo,$mot,$obs);$st->execute();$conn->commit();registrarHistorial($conn,'inventario','ajustar_stock','Stock modificado',['producto'=>$pid,'nombre'=>$p['nombre'],'anterior'=>$an,'nuevo'=>$nuevo,'motivo'=>$mot]);flash('success','Stock actualizado y movimiento guardado.');}catch(Throwable $e){if($conn->in_transaction)$conn->rollback();flash('error',$e->getMessage());}redir('inventario.php');
}
$rows=$conn->query("SELECT p.*,c.nombre categoria FROM productos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.activo=1 ORDER BY p.stock ASC,p.nombre");
$hist=$conn->query("SELECT mi.*,p.nombre producto,u.nombre usuario FROM movimientos_inventario mi JOIN productos p ON p.id=mi.producto_id LEFT JOIN usuarios u ON u.id=mi.usuario_id ORDER BY mi.id DESC LIMIT 250");
?>
<div class="toolbar"><div><span class="eyebrow">INVENTARIO</span><h2>Inventario</h2><p>Controla existencias y conserva el historial de cada entrada, salida o ajuste.</p></div></div>
<section class="panel"><div class="section-head"><div><h3>Stock actual</h3><small>Todo cambio queda registrado.</small></div><input class="search" id="buscarInv" placeholder="Buscar producto..."></div><div class="table-wrap"><table id="inv"><thead><tr><th>Producto</th><th>Categoría</th><th>Stock</th><th>Mínimo</th><th>Nuevo stock</th><th>Motivo</th><th></th></tr></thead><tbody><?php while($p=$rows->fetch_assoc()):$low=(float)$p['stock']<=(float)$p['stock_minimo'];?><tr><td><strong><?=e($p['nombre'])?></strong></td><td><?=e($p['categoria']??'Sin categoría')?></td><td><span class="stock-badge <?=$low?'low':''?>"><?=e($p['stock'])?> <?=e($p['unidad'])?></span></td><td><?=e($p['stock_minimo'])?></td><td><form method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="producto_id" value="<?=$p['id']?>"><input type="number" step="0.01" min="0" name="nuevo_stock" value="<?=e($p['stock'])?>"><input name="motivo" placeholder="Motivo" required><button class="btn small">Guardar</button></form></td><td><?=e($p['unidad'])?></td><td><a class="btn small" href="productos.php?editar=<?=$p['id']?>">Editar</a></td></tr><?php endwhile;?></tbody></table></div></section>
<section class="panel table-wrap"><div class="section-head"><div><h3>Historial de stock</h3><small>Últimos 250 movimientos.</small></div></div><table><thead><tr><th>Fecha</th><th>Producto</th><th>Usuario</th><th>Tipo</th><th>Origen</th><th>Cantidad</th><th>Antes</th><th>Después</th><th>Motivo</th></tr></thead><tbody><?php while($h=$hist->fetch_assoc()):?><tr><td><?=e($h['creado_en'])?></td><td><strong><?=e($h['producto'])?></strong></td><td><?=e($h['usuario']??'Sistema')?></td><td><?=e($h['tipo'])?></td><td><?=e($h['origen'])?></td><td><?=e($h['cantidad'])?></td><td><?=e($h['stock_anterior'])?></td><td><?=e($h['stock_nuevo'])?></td><td><?=e($h['motivo']??'—')?></td></tr><?php endwhile;?></tbody></table></section>
<script>document.getElementById('buscarInv')?.addEventListener('input',function(){let x=this.value.toLowerCase();document.querySelectorAll('#inv tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(x)?'':'none')});</script>
